<script setup lang="ts">
import axios from 'axios';
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import UiDialog from '../design-system/UiDialog.vue';
import { rasterIconSource } from '../design-system/rasterIconAssets';
type Column = 'name' | 'category' | 'scope' | 'recurrence' | 'validity';
interface Occasion { id: number; name: string; occasionCategory: string; territorialScope: string; recurrence: { type: string }; validity: { from: string | null; to: string | null }; }
const allColumns: Column[] = ['name', 'category', 'scope', 'recurrence', 'validity'];
const labels: Record<Column, string> = { name: 'Nome', category: 'Categoria', scope: 'Esfera', recurrence: 'Recorrência', validity: 'Vigência' };
const widths: Record<Column, number> = { name: 320, category: 180, scope: 190, recurrence: 210, validity: 230 };
const emit = defineEmits<{ create: []; edit: [id: number] }>();
const root = ref<HTMLElement | null>(null); const search = ref(''); const rows = ref<Occasion[]>([]); const total = ref(0); const loading = ref(false); const error = ref(''); const selected = ref(new Set<number>()); const keepSelection = ref(false); const selectedOnly = ref(false); const includeHidden = ref(false); const columnsOpen = ref(false); const advancedOpen = ref(false); const visible = ref<Record<Column, boolean>>({ name: true, category: true, scope: true, recurrence: true, validity: true }); const order = ref<Column[]>([...allColumns]); const sort = ref<{ column: Column; direction: 'asc' | 'desc' }>({ column: 'name', direction: 'asc' }); const message = ref(''); const messageOpen = ref(false);
const currentColumns = computed(() => order.value.filter((column) => visible.value[column])); const listedRows = computed(() => selectedOnly.value ? rows.value.filter((row) => selected.value.has(row.id)) : rows.value); const selectedCount = computed(() => selected.value.size); const icons = { funnel: rasterIconSource('funnel', 'sm'), columns: rasterIconSource('tableColumns', 'sm'), clean: rasterIconSource('tableCleanSelection', 'sm'), lock: rasterIconSource('tableLockSelection', 'sm'), selected: rasterIconSource('tableShowSelected', 'sm'), hidden: rasterIconSource('tableShowHiddenSelected', 'sm') };
function notify(text: string): void { message.value = text; messageOpen.value = true; }
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const { data } = await axios.post('/api/v1/platform/calendar-occasions/query', { search: search.value || undefined, sorts: [sort.value], offset: 0, limit: 100, selectedOnly: selectedOnly.value, selectedIds: [...selected.value] }); rows.value = data.calendarOccasions ?? data.data ?? []; total.value = data.range?.total ?? data.pagination?.total ?? rows.value.length; if (!keepSelection.value) selected.value = new Set(); } catch (reason) { if (axios.isAxiosError(reason) && reason.response?.status === 404) { rows.value = []; total.value = 0; return; } error.value = 'Não foi possível carregar as definições de feriados.'; } finally { loading.value = false; } }
function select(id: number): void { const next = new Set(selected.value); next.has(id) ? next.delete(id) : next.add(id); selected.value = next; } function selectAll(): void { selected.value = new Set(listedRows.value.map((row) => row.id)); } function clear(): void { if (!selected.value.size) return notify('Nenhuma definição selecionada.'); selected.value = new Set(); selectedOnly.value = false; includeHidden.value = false; } function edit(): void { if (selectedCount.value !== 1) return notify(selectedCount.value ? 'Selecione apenas uma definição para editar.' : 'Selecione uma definição para editar.'); emit('edit', [...selected.value][0]); } function cell(column: Column, row: Occasion): string { if (column === 'name') return row.name; if (column === 'category') return row.occasionCategory; if (column === 'scope') return row.territorialScope; if (column === 'recurrence') return row.recurrence.type; return `${row.validity.from ?? '—'} até ${row.validity.to ?? '—'}`; } function changeSort(column: Column): void { sort.value = { column, direction: sort.value.column === column && sort.value.direction === 'asc' ? 'desc' : 'asc' }; void load(); } function toggleColumn(column: Column): void { if (visible.value[column] && currentColumns.value.length === 1) return notify('Mantenha ao menos uma coluna visível.'); visible.value = { ...visible.value, [column]: !visible.value[column] }; } function resetColumns(): void { visible.value = { name: true, category: true, scope: true, recurrence: true, validity: true }; order.value = [...allColumns]; } const dragged = ref<Column | null>(null); function drag(column: Column): void { dragged.value = column; } function drop(target: Column): void { const source = dragged.value; if (!source || source === target) return; const next = [...order.value]; next.splice(next.indexOf(source), 1); next.splice(next.indexOf(target), 0, source); order.value = next; dragged.value = null; } async function focus(): Promise<void> { await nextTick(); root.value?.focus(); } defineExpose({ refresh: load, focus }); onMounted(() => void load()); onBeforeUnmount(() => { dragged.value = null; });
</script>
<template>
  <section ref="root" class="calendar-occasion-catalog" tabindex="-1" aria-label="Feriados">
    <header class="toolbar"><div class="search-tools"><label class="search"><span class="sr-only">Pesquisar definições de feriados</span><input v-model="search" type="search" placeholder="Pesquisar por nome" @keydown.enter.prevent="load"><button type="button" aria-label="Pesquisar" @click="load"><img :src="'/assets/icons/search_24.png'" alt=""></button></label><button class="ui-icon-button filter" type="button" aria-label="Filtros avançados" :aria-pressed="advancedOpen" @click="advancedOpen = true"><img :src="icons.funnel ?? '/assets/icons/funnel_24.png'" alt=""></button></div><div class="toolbar-actions"><div class="selection-tools"><button class="ui-icon-button" type="button" aria-label="Manter seleção" :aria-pressed="keepSelection" @click="keepSelection = !keepSelection"><img :src="icons.lock ?? '/assets/icons/tableLockSelection_24.png'" alt=""></button><button class="ui-icon-button" type="button" aria-label="Mostrar selecionados" :aria-pressed="selectedOnly" @click="selectedOnly = !selectedOnly"><img :src="icons.selected ?? '/assets/icons/tableShowSelected_24.png'" alt=""></button><button class="ui-icon-button" type="button" aria-label="Incluir selecionados ocultos" :aria-pressed="includeHidden" @click="includeHidden = !includeHidden"><img :src="icons.hidden ?? '/assets/icons/tableShowHiddenSelected_24.png'" alt=""></button><button class="ui-icon-button" type="button" aria-label="Limpar seleção" @click="clear"><img :src="icons.clean ?? '/assets/icons/tableCleanSelection_24.png'" alt=""></button></div><button class="ui-icon-button" type="button" aria-label="Colunas" :aria-expanded="columnsOpen" @click="columnsOpen = !columnsOpen"><img :src="icons.columns ?? '/assets/icons/tableColumns_24.png'" alt=""></button></div><aside v-if="columnsOpen" class="columns"><p>Colunas</p><button v-for="column in allColumns" :key="column" type="button" :class="{ active: visible[column] }" @click="toggleColumn(column)"><span>{{ visible[column] ? '✓' : '' }}</span>{{ labels[column] }}</button><button class="ui-button ui-button--secondary" type="button" @click="resetColumns">Restaurar colunas</button></aside></header>
    <p v-if="error" class="feedback" role="alert">{{ error }} <button type="button" @click="load">Tentar novamente</button></p>
    <div class="grid"><table><thead><tr><th class="selection"><input type="checkbox" :checked="total > 0 && selectedCount === total" aria-label="Selecionar todas" @change="selectAll"></th><th v-for="column in currentColumns" :key="column" :style="{ width: `${widths[column]}px` }" draggable="true" @dragstart="drag(column)" @dragover.prevent @drop="drop(column)"><button class="sort" type="button" @click="changeSort(column)">{{ labels[column] }} <span v-if="sort.column === column">{{ sort.direction === 'asc' ? '▲' : '▼' }}</span></button></th></tr></thead><tbody><tr v-for="row in listedRows" :key="row.id" @dblclick="emit('edit', row.id)"><td class="selection"><input type="checkbox" :checked="selected.has(row.id)" :aria-label="row.name" @change="select(row.id)"></td><td v-for="column in currentColumns" :key="column" :style="{ width: `${widths[column]}px` }">{{ cell(column, row) }}</td></tr><tr v-if="!loading && !listedRows.length"><td :colspan="currentColumns.length + 1">Nenhuma definição encontrada.</td></tr></tbody></table><p v-if="loading" role="status">Carregando definições de feriados…</p></div>
    <footer class="status" role="status">{{ total }} definições encontradas.<template v-if="selectedCount"> · {{ selectedCount }} selecionada(s).</template></footer><footer class="actions"><button class="ui-button ui-button--secondary" type="button" @click="emit('create')"><img :src="'/assets/icons/dataInsert_24.png'" alt="">Inserir</button><button class="ui-button ui-button--secondary" type="button" @click="edit"><img :src="'/assets/icons/dataEdit_24.png'" alt="">Alterar</button><button class="ui-button ui-button--secondary" type="button" @click="edit"><img :src="'/assets/icons/dataView_24.png'" alt="">Visualizar</button><button class="ui-button ui-button--destructive" type="button" @click="notify('A exclusão será disponibilizada junto da API de Feriados.')"><img :src="'/assets/icons/dataDelete_24.png'" alt="">Excluir</button></footer>
    <UiDialog v-model="advancedOpen" contained title="Filtros avançados"><p>Os filtros avançados serão habilitados junto do contrato de consulta de Feriados.</p><button class="ui-button ui-button--secondary" type="button" @click="advancedOpen = false">Fechar</button></UiDialog><UiDialog v-model="messageOpen" contained title="Feriados"><p>{{ message }}</p><button class="ui-button ui-button--secondary" type="button" @click="messageOpen = false">Fechar</button></UiDialog>
  </section>
</template>
<style scoped>
