er:0;background:transparent;color:var(--color-text-secondary);text-align:start}.columns>button:not(.ui-button) span{display:grid;width:1.25rem;height:1.25rem;place-items:center;border:var(--component-border-width) solid var(--color-border-strong);border-radius:var(--radius-sm)}.columns>button.active span{border-color:var(--color-action-primary);background:var(--color-action-primary);color:var(--color-action-primary-content)}.grid{min-block-size:0;overflow:auto;border:var(--component-border-width) solid var(--color-border-subtle);border-radius:var(--radius-lg) var(--radius-lg) 0 0;background:var(--color-surface)}table{width:100%;min-width:48rem;border-collapse:collapse;table-layout:fixed}thead{position:sticky;z-index:1;inset-block-start:0;background:color-mix(in srgb,var(--color-surface-muted) 72%,var(--color-surface-raised));box-shadow:0 1px 0 var(--color-border-strong)}tbody tr:nth-child(even){background:color-mix(in srgb,var(--color-surface-muted) 48%,var(--color-surface))}tbody tr:hover{background:color-mix(in srgb,var(--color-action-primary) var(--color-mix-subtle),var(--color-surface-muted))}th,td{padding:var(--space-2) var(--space-3);border-bottom:var(--component-border-width) solid var(--color-border-subtle);color:var(--color-text-primary);text-align:start;white-space:nowrap}.selection{width:3rem}.sort{width:100%;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:var(--font-weight-bold);text-align:start;cursor:pointer}.status{margin-block-start:calc(var(--space-3) * -1);padding:var(--space-2) var(--space-3);border:var(--component-border-width) solid var(--color-border-subtle);border-top:0;border-radius:0 0 var(--radius-lg) var(--radius-lg);background:var(--color-surface-muted);color:var(--color-text-secondary)}.actions{justify-content:end}.actions .ui-button--destructive{border-color:var(--color-danger-700)}.feedback{position:absolute;z-index:3;inset-block-start:calc(var(--control-height-md) + var(--space-4));inset-inline:var(--s